const D = { energy:.6, scale:1, density:.5, speed:1, shear:.55, reach:.5, alpha:.72, hue:212, x:.5, y:.28, style:'overcast', act:'drift', seed:0 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const clp=(v,a,b)=>Math.max(a,Math.min(b,v));
const lrp=(a,b,t)=>a+(b-a)*t;
const md=(a,n)=>((a%n)+n)%n;
const frc=v=>v-Math.floor(v);
const fr=i=>{const s=Math.sin(i*127.1+P.seed*311.7)*43758.5453;return s-Math.floor(s);};
const hsb2=(h,s,v)=>{h=md(h,360)/60;s=clp(s,0,1);v=clp(v,0,1);const c=v*s,x=c*(1-Math.abs(h%2-1)),m=v-c;let r=0,g=0,b=0;
  if(h<1){r=c;g=x;}else if(h<2){r=x;g=c;}else if(h<3){g=c;b=x;}else if(h<4){g=x;b=c;}else if(h<5){r=x;b=c;}else{r=c;b=x;}
  return [(r+m)*255,(g+m)*255,(b+m)*255];};

const W=width, Hh=height, u=Math.min(W,Hh);
const H=md(P.hue,360), HO=H-212;
const st=P.style, act=P.act||'drift';
const isSun=st==='sunset', isDst=st==='dust', isRad=st==='radar', isEng=st==='engraving';
const en=clp(P.energy,0,1), dn=clp(P.density,0,1), al=clp(P.alpha,0,1);
const sc=clp(P.scale,0.4,2.0), sp=clp(P.speed,0.1,4), rch=clp(P.reach,0,1);
if(S.lastBeat==null||K.beat<S.lastBeat)S.lastBeat=K.beat; S.lastBeat=K.beat;

const MAXN=18;
if(S.seedUsed!==P.seed||!S.sh){
  S.seedUsed=P.seed;
  S.nt=new Float32Array(257);
  for(let i=0;i<256;i++) S.nt[i]=fr(i*1.71+3.3);
  S.nt[256]=S.nt[0];
  S.sh=[];
  for(let k=0;k<MAXN;k++) S.sh.push({
    T: 15+fr(k*3+1)*27,                                  // 15-42 s life, incommensurate across shafts
    o: fr(k*5+2),
    x0: fr(k*7+3),
    dr: (0.006+fr(k*11+4)*0.020)*(fr(k*13+5)>0.42?1:-1), // own drift rate + direction
    hw: 0.030+fr(k*17+6)*0.052,
    rm: 0.42+fr(k*19+7)*0.58,
    str: 0.55+fr(k*23+8)*0.45,
    ph: fr(k*29+9)*97.3
  });
}
const NT=S.nt;
const n1=x=>{const f=x-Math.floor(x); const i=((Math.floor(x)%256)+256)%256; return NT[i]+(NT[i+1]-NT[i])*(f*f*(3-2*f));};

const t=K.t*sp;
// ---- act programmes: real-time envelopes at incommensurate rates, never a beat-locked loop ----
const slow=0.5+0.5*Math.sin(K.t*0.029*sp+0.7);
let fallMul=1, envA=1, reachMul=1;
if(act==='microburst'){ fallMul=1+1.5*Math.pow(clp(0.5+0.5*Math.sin(K.t*0.047*sp),0,1),3); envA=0.85+0.5*slow; reachMul=1+0.30*Math.pow(clp(0.5+0.5*Math.sin(K.t*0.047*sp+0.8),0,1),2.5); }
else if(act==='dissipate'){ envA=0.30+0.95*Math.pow(slow,0.8); reachMul=0.55+0.65*slow; }
else { envA=0.82+0.30*Math.sin(K.t*0.041*sp+1.9); reachMul=1+0.10*Math.sin(K.t*0.083*sp); }
const arc=0.72+0.55*K.intensity;
envA*=arc;
const shr=clp(P.shear,-1,1)*(0.16+0.30*en)*(1+0.22*Math.sin(K.t*0.061*sp+2.4));
const fall=(0.55+1.6*en)*fallMul*sp*(1+A.bass*0.4);
const baseY=clp(P.y,-0.2,0.9);
const span=Math.max(0.12,(1-baseY)*1.18);
const nSh=Math.max(2,Math.round(lrp(3,MAXN,dn)));

// ---- coarse density field ----
const bw=160, bh=clp(Math.round(160*Hh/W),60,200);
if(!S.g||S.bw!==bw||S.bh!==bh){ S.g=createGraphics(bw,bh); S.g.pixelDensity(1); S.bw=bw; S.bh=bh; S.acc=new Float32Array(bw*bh); }
const g=S.g, acc=S.acc;
acc.fill(0);

// ---- cloud base: ragged underside, mamma lobes, a broad drifting mass (the area element) ----
{
  const bAmt=(0.74+0.72*en)*envA;
  for(let col=0;col<bw;col++){
    const under=baseY + 0.052*n1(col*0.13+t*0.031) + 0.022*Math.sin(col*0.21+t*0.113) + 0.012*Math.sin(col*0.47+t*0.191+1.3);
    const ur=under*bh;
    const r1=Math.max(0,Math.floor(ur));
    for(let row=0;row<=r1&&row<bh;row++){
      const d=(ur-row)/bh;
      const prof=clp(d/0.085,0,1)*clp(1-d/(baseY+0.34),0,1);
      if(prof<=0) continue;
      acc[row*bw+col]+=bAmt*prof*(0.62+0.62*n1(col*0.075+row*0.055+t*0.019+11.7));
    }
  }
}

// ---- the shafts: born, extend, fray, evaporate, die, respawn — perpetual, never converges ----
const fray=new Float32Array(bw);
for(let k=0;k<nSh;k++){
  const s=S.sh[k];
  const p=frc(t/s.T+s.o);
  const life=Math.pow(Math.sin(Math.PI*p),0.75)*envA;
  if(life<0.03) continue;
  const grow=clp(p*3.4,0,1);
  const tip=s.rm*lrp(0.25,1.0,rch)*(0.34+0.72*grow)*reachMul;
  if(tip<=0.02) continue;
  const cxf=frc(s.x0+s.dr*t)*1.34-0.17;
  const hw0=s.hw*sc;
  for(let col=0;col<bw;col++) fray[col]=0.74+0.40*n1(col*0.085+s.ph+t*0.17);
  const r0=Math.max(0,Math.floor(baseY*bh));
  for(let row=r0;row<bh;row++){
    const yn=(row/bh-baseY)/span;
    if(yn<0) continue;
    const cx=(cxf+shr*Math.pow(yn,1.5))*bw;
    const hw=hw0*(0.50+1.15*yn)*bw;
    if(hw<0.6) continue;
    const x0=Math.max(0,Math.floor(cx-hw)), x1=Math.min(bw-1,Math.ceil(cx+hw));
    if(x1<x0) continue;
    let any=false;
    for(let col=x0;col<=x1;col++){
      const f=yn/(tip*fray[col]);
      if(f>=1) continue;
      const d=(col-cx)/hw;
      const prof=1-d*d;
      if(prof<=0) continue;
      const env=Math.pow(1-f,1.35);
      const striat=0.66+0.62*n1(col*1.05+row*0.16-t*fall*2.4+s.ph);
      acc[row*bw+col]+=s.str*life*env*prof*striat;
      any=true;
    }
    if(!any&&yn>tip*1.2) break;
  }
}

// ---- map density -> colour (style is a different rendering philosophy, not a hue swap) ----
g.loadPixels();
const pix=g.pixels;
for(let i=0;i<bw*bh;i++){
  const a=acc[i];
  if(a<=0.006){ pix[4*i+3]=0; continue; }
  const e=clp(a*0.90,0,1);
  let hh,ss,vv,aa;
  if(isSun){ hh=HO+lrp(320,44,Math.pow(e,0.62)); ss=lrp(0.58,0.24,Math.pow(e,1.3)); vv=lrp(0.33,1,Math.pow(e,0.62)); aa=clp(a*0.95,0,0.95); }
  else if(isDst){ hh=HO+lrp(20,46,e); ss=lrp(0.60,0.20,Math.pow(e,1.2)); vv=lrp(0.27,0.90,Math.pow(e,0.7)); aa=clp(a*0.96,0,0.96); }
  else if(isRad){ const q=Math.min(5,Math.floor(e*6)); const HR=[206,178,132,58,26,318], VR=[0.42,0.60,0.78,0.92,0.98,0.9]; hh=HO+HR[q]; ss=q>=5?0.78:0.86; vv=VR[q]; aa=clp(0.16+q*0.155,0,0.9); }
  else if(isEng){ const hatch=Math.abs(frc((i%bw)*0.62+Math.floor(i/bw)*0.30)*2-1); const ink=clp(Math.pow(e,0.75)-hatch*0.72,0,1); hh=HO+206; ss=lrp(0.22,0.05,e); vv=lrp(0.50,1,e); aa=clp(ink*2.3,0,0.92); }
  else { hh=H+lrp(8,-10,e); ss=lrp(0.32,0.07,Math.pow(e,1.1)); vv=lrp(0.31,0.95,Math.pow(e,0.68)); aa=clp(a*0.94,0,0.94); }
  const col=hsb2(hh,ss,vv);
  pix[4*i]=col[0]; pix[4*i+1]=col[1]; pix[4*i+2]=col[2]; pix[4*i+3]=aa*255;
}
g.updatePixels();

// ---- backlight behind the base (broad, additive, wanders on incommensurate rates) ----
blendMode(ADD);
{
  const lx=(clp(P.x,-0.2,1.2)+0.13*Math.sin(K.t*0.053*sp)+0.07*Math.sin(K.t*0.127*sp+1.1))*W;
  const ly=(baseY+0.08+0.03*Math.sin(K.t*0.071*sp+0.5))*Hh;
  const R=Math.max(10,u*(0.55+0.30*en)*(1+0.10*Math.sin(K.t*0.037*sp)));
  const gc=hsb2(isSun?HO+34:isDst?HO+38:isRad?HO+186:isEng?HO+200:H+6, isSun?0.42:isDst?0.40:isRad?0.55:0.14, 1);
  const ga=clp((isEng?0.12:0.22)*al*(0.4+0.8*en)*(0.75+0.55*K.intensity)*(1+A.rms*0.4),0,0.30);
  const gr=drawingContext.createRadialGradient(lx,ly,0,lx,ly,R);
  gr.addColorStop(0,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+','+ga.toFixed(3)+')');
  gr.addColorStop(0.5,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+','+(ga*0.4).toFixed(3)+')');
  gr.addColorStop(1,'rgba('+(gc[0]|0)+','+(gc[1]|0)+','+(gc[2]|0)+',0)');
  drawingContext.fillStyle=gr;
  drawingContext.fillRect(0,0,W,Hh);
}
blendMode(BLEND);

tint(0,0,100,clp(al,0,1)*100);
image(g,0,0,W,Hh);
noTint();

// ---- fall streaks: fine detail riding on the field, never carrying it ----
if(!isEng){
  blendMode(ADD);
  const ns=Math.round(lrp(14,90,dn));
  for(let i=0;i<ns;i++){
    const k=i%nSh, s=S.sh[k];
    const p=frc(t/s.T+s.o);
    const life=Math.pow(Math.sin(Math.PI*p),0.75)*envA;
    if(life<0.12) continue;
    const grow=clp(p*3.4,0,1);
    const tip=s.rm*lrp(0.25,1.0,rch)*(0.34+0.72*grow)*reachMul;
    const yn=frc(fr(i*7+13)+t*fall*0.06)*tip;
    const cxf=frc(s.x0+s.dr*t)*1.34-0.17;
    const jx=(fr(i*11+5)*2-1)*s.hw*sc*(0.5+1.15*yn)*0.85;
    const px=(cxf+shr*Math.pow(yn,1.5)+jx)*W;
    const py=(baseY+yn*span)*Hh;
    if(px<-30||px>W+30||py>Hh+20) continue;
    const fade=Math.pow(clp(1-yn/tip,0,1),1.1)*life;
    const ln=u*lrp(0.012,0.048,fr(i*13+2))*(0.4+1.3*en)*sc;
    const aa=clp((10+52*fade)*al*(0.3+0.9*en),0,58);
    if(aa<2) continue;
    stroke(isSun?HO+lrp(320,46,fade):isDst?HO+42:isRad?HO+58:H-lrp(4,14,fade), isSun?lrp(46,16,fade):isRad?70:lrp(28,6,fade), lrp(58,100,fade), aa);
    strokeWeight(Math.max(0.4,u*0.0011*sc*(0.5+fr(i*17+3))));
    line(px,py,px+shr*ln*1.4,py+ln);
  }
  noStroke();
  blendMode(BLEND);
}

// ---- radar instrument furniture (the abstracted read) ----
if(isRad){
  const cx=clp(P.x,-0.2,1.2)*W, cy=Hh*1.02;
  noFill(); stroke(HO+186,55,90,clp(26*al,0,34)); strokeWeight(Math.max(0.6,u*0.0011));
  for(let i=1;i<=4;i++) circle(cx,cy,u*i*0.42*(1+0.012*Math.sin(K.t*0.29+i)));
  for(let i=0;i<7;i++){ const a=-Math.PI/2+(i-3)*0.32; line(cx,cy,cx+Math.cos(a)*u*0.9,cy+Math.sin(a)*u*0.9); }
  noStroke();
}

blendMode(BLEND); drawingContext.shadowBlur=0; noTint();
